class sample
{
    public int i;
    public int[] arr = new int[10];
    public void fun(int i, int val)
    {
        arr[i] = val;
    }
}
class Program
{
    static void Main(string[] args)
    {
        sample s = new sample();
        s.i = 10;
        sample.fun(1, 5);
        s.fun(1, 5);
        Console.ReadLine();
    }
}

questions.explanation:
An Object reference is required for non static field, method or property. i.e

                      sample s = new sample();
                      s.i = 10;
                      sample.fun(1, 5);
                      sample.fun(1, 5);
                      Console.ReadLine();

General form of class declaration in C# is :

class  class_name
{
       member variables
         variable1;
         variable2;
         variableN;
         method1(parameter_list)
       {
             method body
       }
         method2(parameter_list)
       {
            method body
       }
         methodN(parameter_list)
       {
            method body
       }
}

